const {PostgresThreadInputRepository}=require(dir+'/repository.cjs');
const db=new PGlite();const statements=[];
function client(handle){return {async query(sql,params){statements.push(sql);const r=await handle.query(sql,params);return {rows:r.rows,rowCount:r.affectedRows??r.rows.length};},transaction:fn=>handle.transaction?handle.transaction(t=>fn(client(t))):fn(client(handle))};}
const scope={sessionId:'33333333-3333-4333-8333-333333333333',userId:'11111111-1111-4111-8111-111111111111',workspaceId:'22222222-2222-4222-8222-222222222222',threadId:'thr_'+'a'.repeat(24)};
const repo=new PostgresThreadInputRepository(client(db));const content={...scope,delivery:'steer',targetTurnId:'trn_'+'b'.repeat(24),targetRunAttemptId:'attempt_'+'c'.repeat(24),text:'text',mediaRefs:[],configuration:{}};
(async()=>{
await db.exec('CREATE TABLE sessions(id UUID PRIMARY KEY,user_id UUID,thread_id TEXT,workspace_id UUID)');
await db.query('INSERT INTO sessions VALUES($1,$2,$3,$4)',[scope.sessionId,scope.userId,scope.threadId,scope.workspaceId]);
const migration=fs.readFileSync(root+'/packages/persistence/src/migrations/0033-thread-inputs-and-continuations.ts','utf8');
for(const name of ['thread_input_state','thread_inputs']){const re=new RegExp('`(CREATE TABLE IF NOT EXISTS '+name+' \\([\\s\\S]*?\\))`');const m=migration.match(re);assert(m);await db.exec(m[1]);}
const miss=await repo.getByClientInputId({...scope,clientInputId:'new'});assert.equal(miss,null);assert.equal((await db.query('SELECT count(*) AS n FROM thread_input_state')).rows[0].n,0);
const inserted=await repo.enqueue({...content,clientInputId:'same',fingerprint:'fixed'});const id=inserted.item.itemId;
const before=JSON.stringify((await db.query('SELECT * FROM thread_input_state')).rows);const start=statements.length;
for(const state of ['pending','consuming','consumed','cancelled']){await db.query('UPDATE thread_inputs SET state=$2 WHERE id=$1',[id,state]);const got=await repo.getByClientInputId({...scope,clientInputId:'same'});assert.equal(got.state,state);assert.equal(got.fingerprint,'fixed');}
assert.equal(JSON.stringify((await db.query('SELECT * FROM thread_input_state')).rows),before);assert(statements.slice(start).every(s=>s.trim().startsWith('SELECT')));
await assert.rejects(repo.getByClientInputId({...scope,userId:'99999999-9999-4999-8999-999999999999',clientInputId:'same'}));
const captured={...scope,clientInputId:'same'};const pending=repo.getByClientInputId(captured);captured.clientInputId='other';assert.equal((await pending).itemId,id);
// Actual PostgreSQL-WASM transactions, two legal orderings. Null is only this
// read's linearization point, not proof a later same-ID request never accepts.
const [old]=await Promise.all([repo.getByClientInputId({...scope,clientInputId:'read-first'}),repo.enqueue({...content,clientInputId:'read-first',fingerprint:'one'})]);assert.equal(old,null);assert(await repo.getByClientInputId({...scope,clientInputId:'read-first'}));
const [write,newer]=await Promise.all([repo.enqueue({...content,clientInputId:'write-first',fingerprint:'two'}),repo.getByClientInputId({...scope,clientInputId:'write-first'})]);assert.equal(newer.itemId,write.item.itemId);
fs.writeFileSync(dir+'/pg-result.json',JSON.stringify({engine:'PGlite 0.3.16 actual PostgreSQL WASM',allStates:['pending','consuming','consumed','cancelled'],readOnlyLookup:true,noStateAllocationOnAbsence:true,scopeFailure:true,inputSnapshot:true,transactionOrderings:2,revisionOrderTimestampPreserved:true,scope:'actual repository source+existing table DDL; no external database/account/provider'},null,2)+'\n');
await db.close();console.log('actual repository/PostgreSQL-WASM all-state readonly and ordering controls passed');
})().catch(async e=>{console.error(e.stack);await db.close();process.exitCode=1;});
